export interface ListBookingPoliciesRequest {
  /**
   * IDs of services to retrieve booking policies for.
   * @format GUID
   * @minSize 1
   * @maxSize 8
   */
  serviceIds: string[];
}

export interface ListBookingPoliciesResponse {
  /** Booking policies for the requested services. */
  bookingPolicies?: BookingPolicy[];
}

export interface BookingPolicy {
  /**
   * Service ID.
   * @format GUID
   */
  serviceId?: string;
  /** Policy for limiting early bookings. */
  limitEarlyBooking?: LimitEarlyBooking;
  /** Policy for limiting late bookings. */
  limitLateBooking?: LimitLateBooking;
  /** Policy for allowing online bookings. */
  onlineBooking?: OnlineBooking;
  /**
   * Policy for class waiting lists.
   * @internal
   */
  waitingList?: WaitingList;
  /**
   * ID of the booking policy.
   * @internal
   * @format GUID
   */
  policyId?: string | null;
  /** Rules for Intake Form integration */
  intakeFormPolicy?: IntakeFormPolicy;
  /**
   * Policy for booking a service after it started. Relevant for courses. When omitted, it is not allowed.
   * @internal
   */
  bookAfterStartPolicy?: BookAfterStartPolicy;
}

export interface LimitEarlyBooking {
  /**
   * Whether there's a limit on how early a customer can book. If `false`, customers can book as far in advance as they want.
   *
   * Default: `false`
   */
  enabled?: boolean;
  /**
   * Maximum number of minutes before the slot start time that a booking can be made. Must be greater than `latestBookingInMinutes`.
   *
   * Default: `10080` (7 days)
   * @min 1
   */
  earliestBookingInMinutes?: number | null;
}

export interface LimitLateBooking {
  /**
   * Whether there's a limit on how late a customer can book. If `false`, customers can book up to the last minute.
   *
   * Default: `false`
   */
  enabled?: boolean;
  /**
   * Minimum number of minutes before the slot start time that a booking can be made. Must be less than `earliestBookingInMinutes`.
   *
   * Default: `1440` (1 day)
   * @min 1
   */
  latestBookingInMinutes?: number | null;
}

export interface OnlineBooking {
  /**
   * Whether the service can be booked online.
   *
   * Default: `true`
   */
  enabled?: boolean | null;
}

export interface WaitingList {
  /**
   * Whether the service has a waitlist.
   *
   * Default: `false`
   */
  enabled?: boolean;
  /**
   * Number of spots available in the waitlist.
   *
   * Default: `10`
   * @min 1
   */
  totalCapacity?: number | null;
  /**
   * Time in minutes a customer has to complete a booking after being notified of an available spot.
   *
   * Default: `10`
   * @min 1
   */
  holdTimeInMinutes?: number | null;
}

export interface IntakeFormPolicy {
  /**
   * ID of the form used as an intake form for the service.
   * @format GUID
   */
  formId?: string | null;
  /**
   * Whether the intake form must be completed before booking. If `false`, the form is handled after booking.
   *
   * Default: `false`
   */
  requireBeforeBook?: boolean;
}

export interface BookAfterStartPolicy {
  /**
   * Whether a customer can still book after the service has started. Relevant for courses,
   * where enrollment can remain open once the first session has started. When `true`, only the
   * remaining sessions of the course can be booked.
   *
   * Default: `false`
   */
  enabled?: boolean;
}

export interface BookingPolicyProviderConfig {
  /** Base URI where your service plugin endpoints are deployed. For example, `https://my-app.com`. */
  deploymentUri?: SpiBaseUri;
  /**
   * Display name for the provider.
   * @maxLength 100
   */
  providerName?: string | null;
}

/** Base URI configuration for a service plugin. Wix uses these URIs to call your service plugin methods. */
export interface SpiBaseUri {
  /**
   * Base URI for your service plugin. Wix appends each method's path to this URI.
   *
   * For example, to receive requests at `https://my-app.com/v1/my-method`, set this field to `https://my-app.com/`.
   * @minLength 6
   * @maxLength 2048
   */
  baseUri?: string;
  /** Alternative URIs for specific methods. Use these to override the default URI for individual methods. */
  alternativeUris?: AlternativeUri[];
}

/** Custom URI for the specified service plugin method. */
export interface AlternativeUri {
  /**
   * Name of the method to call at the absolute URI, in PascalCase. For example, to call [Get Shipping Rates](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/extensions/shipping-rates/shipping-rates-integration-service-plugin/get-shipping-rates) on an alternative URI, specify `GetShippingRates`.
   * @minLength 3
   * @maxLength 128
   */
  methodName?: string;
  /**
   * Absolute URI that Wix calls for this method. Wix doesn't append any path to this URI.
   *
   * The URI must begin with `https://`, such as `https://my-app.com/v1/my-custom-method`.
   * @minLength 6
   * @maxLength 2048
   */
  absoluteUri?: string;
}

/**
 * this message is not directly used by any service,
 * it exists to describe the expected parameters that SHOULD be provided to invoked Velo methods as part of open-platform.
 * e.g. SPIs, event-handlers, etc..
 * NOTE: this context object MUST be provided as the last argument in each Velo method signature.
 *
 * Example:
 * ```typescript
 * export function wixStores_onOrderCanceled({ event, metadata }: OrderCanceledEvent) {
 * ...
 * }
 * ```
 */
export interface Context {
  /** A unique identifier of the request. You may print this ID to your logs to help with future debugging and easier correlation with Wix's logs. */
  requestId?: string | null;
  /**
   * [ISO 4217](https://en.wikipedia.org/wiki/ISO_4217) 3-letter currency code.
   * @format CURRENCY
   */
  currency?: string | null;
  /** An object that describes the identity that triggered this request. */
  identity?: IdentificationData;
  /** A string representing a language and region in the format of `"xx-XX"`. First 2 letters represent the language code according to ISO 639-1. This is followed by a dash "-", and then a by 2 capital letters representing the region according to ISO 3166-2. For example, `"en-US"`. */
  languages?: string[];
  /**
   * The service provider app's instance ID.
   * @format GUID
   */
  instanceId?: string | null;
  /**
   * Extension ID in Dev Center.
   * @internal
   * @maxLength 256
   */
  appExtensionId?: string | null;
  /**
   * Extension type in Dev Center.
   * @internal
   * @maxLength 256
   */
  appExtensionType?: string | null;
  /**
   * Invoked function.
   * @internal
   * @maxLength 256
   */
  functionName?: string | null;
}

export enum IdentityType {
  UNKNOWN = 'UNKNOWN',
  ANONYMOUS_VISITOR = 'ANONYMOUS_VISITOR',
  MEMBER = 'MEMBER',
  WIX_USER = 'WIX_USER',
  APP = 'APP',
}

export interface IdentificationData extends IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
  /** @readonly */
  identityType?: IdentityType;
}

/** @oneof */
export interface IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
}
